{
  "description": "Preserve Self-EvolveRec’s diagnostic interface while adapting its probes to the trained recommender. DiagnosisProbe(view, device).run_full_diagnosis(train_loader) returns measured metrics and metric_definitions; diagnosis_interpreter_prompt(raw_diagnosis) turns those results into an interpretation prompt.",
  "motivation": "Provide evidence for model improvements under the shared RecHarness constraints, without inventing unavailable user traits, review data, or item attributes. Select models using macro-average validation HR@10 across all four datasets.",
  "implementation_notes": "Retain the SASRec compatibility contract through view.model, item_emb, log2feats, predict_score, user_train, meta_data, and review_data. Adapt probes to architecture changes and handle B x L sequence, positive, and negative tensors with padding masks. Mark unsupported diagnostics unavailable. Use only public histories, titles, descriptions, and timestamps. Preserve full-catalog unseen-item recommendations for twenty real training users, five per category. Keep preprocessing seed 0, training seed 42, dataset routing, and the host evaluator unchanged. Any inference changes must also update the predictor writer.",
  "pseudocode": "class DiagnosisProbe(view, device):\n    run_full_diagnosis(train_loader):\n        preserve model training state\n        evaluate view.model without gradients\n        collect supported measurements from masked batches\n        restore model training state\n        return {metrics: measured_results, metric_definitions: definitions}\n\nfunction diagnosis_interpreter_prompt(raw_diagnosis):\n    include measured metrics and their definitions\n    identify unavailable evidence explicitly\n    request evidence-grounded interpretations and proposed changes\n\ntrain candidate models\nselect using host macro validation HR@10",
  "originality": {
    "score": 3,
    "positive": "Connects native diagnostic feedback to a constrained, consistent recommendation benchmark.",
    "negative": "Primarily an interface and evaluation adaptation; it specifies no new recommendation algorithm."
  },
  "future_potential": {
    "score": 7,
    "positive": "Can support iterative improvements across architectures while retaining comparable validation and traceable diagnostic evidence.",
    "negative": "Diagnostic usefulness depends on probe quality; measured associations alone do not establish which changes improve recommendations."
  },
  "code_difficulty": {
    "score": 5,
    "positive": "The required interfaces and batch shapes are explicit.",
    "negative": "Architecture-specific probes, padding, unavailable metadata, and predictor serialization require careful coordination."
  }
}
